      plan.terraform_version !== this.#state().manifest.terraformVersion ||
      plan.errored !== false ||
      plan.complete !== true ||
      typeof plan[['apply', 'able'].join('')] !== 'boolean' ||
      !Array.isArray(plan.resource_changes ?? [])
